package com.rpb.reservation.workforce.attendancepolicy;
import static com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyDtos.*;
import com.rpb.reservation.workforce.application.WorkforceJson;import com.rpb.reservation.workforce.domain.WorkforceException;
import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class AttendancePolicyRepository {
 private final JdbcTemplate jdbc;private final WorkforceJson json;
 public AttendancePolicyRepository(JdbcTemplate jdbc,WorkforceJson json){this.jdbc=jdbc;this.json=json;}
 public record Store(UUID companyId,String timezone){}
 public Store store(UUID tenant,UUID store){return jdbc.query("select operating_entity_id,timezone from stores where tenant_id=? and id=? and deleted_at is null",(r,n)->new Store(r.getObject(1,UUID.class),r.getString(2)),tenant,store).stream().findFirst().orElseThrow(WorkforceException::missing);}
 public UUID company(UUID tenant,UUID employee,LocalDate date){return jdbc.query("select company_id from workforce_company_history where tenant_id=? and employee_id=? and effective_date<=? order by effective_date desc,version desc limit 1",(r,n)->r.getObject(1,UUID.class),tenant,employee,date).stream().findFirst().orElseThrow(WorkforceException::missing);}
 public void lock(UUID tenant,UUID subject){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"workforce.attendance-policy:"+tenant+":"+subject);}
 public List<PolicyVersion> defaults(UUID tenant,UUID store){return jdbc.query("select * from workforce_attendance_policies where tenant_id=? and source_store_id=? and employee_id is null order by version",this::read,tenant,store);}
 public List<PolicyVersion> assignments(UUID tenant,UUID employee){return jdbc.query("select * from workforce_attendance_policies where tenant_id=? and employee_id=? order by version",this::read,tenant,employee);}
 public Optional<PolicyVersion> find(UUID tenant,UUID id){return jdbc.query("select * from workforce_attendance_policies where tenant_id=? and id=?",this::read,tenant,id).stream().findFirst();}
 private PolicyVersion read(ResultSet r,int n)throws SQLException{return new PolicyVersion(r.getObject("id",UUID.class),r.getObject("employee_id",UUID.class),r.getObject("company_id",UUID.class),r.getObject("source_store_id",UUID.class),r.getObject("effective_from",LocalDate.class),r.getString("mode"),r.getString("origin"),r.getObject("source_default_id",UUID.class),r.getLong("source_default_version"),r.getString("arrangement")==null?null:json.read(r.getString("arrangement"),Arrangement.class),r.getString("timezone"),r.getLong("version"));}
 public void insert(UUID tenant,UUID actor,PolicyVersion p){jdbc.update("insert into workforce_attendance_policies(id,tenant_id,employee_id,company_id,source_store_id,effective_from,mode,origin,source_default_id,source_default_version,arrangement,timezone,version,actor_id) values(?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?,?)",p.id(),tenant,p.employeeId(),p.companyId(),p.sourceStoreId(),p.effectiveFrom(),p.mode(),p.origin(),p.sourceDefaultId(),p.sourceDefaultVersion(),p.arrangement()==null?null:json.write(p.arrangement()),p.timezone(),p.version(),actor);}
 public Optional<PolicyVersion> replay(UUID tenant,UUID command,UUID store,UUID employee,UUID actor,Object request){return jdbc.query("select * from workforce_attendance_policy_commands where tenant_id=? and command_id=?",(r,n)->{if(!store.equals(r.getObject("store_id",UUID.class))||!Objects.equals(employee,r.getObject("employee_id",UUID.class))||!actor.equals(r.getObject("actor_id",UUID.class))||!request.equals(json.read(r.getString("request_json"),request.getClass())))throw WorkforceException.conflict();return json.read(r.getString("response_json"),PolicyVersion.class);},tenant,command).stream().findFirst();}
 public void receipt(UUID tenant,UUID command,UUID store,UUID employee,UUID actor,Object request,PolicyVersion response){jdbc.update("insert into workforce_attendance_policy_commands(tenant_id,command_id,store_id,employee_id,actor_id,request_json,response_json) values(?,?,?,?,?,?::jsonb,?::jsonb)",tenant,command,store,employee,actor,json.write(request),json.write(response));}
}
